  function resetStock(){if(!isAdmin())return;const word=prompt('This clears current demo items and definitions (releases are retained in history but released lines will be archived in backup). Type CLEAR DEMO STOCK to continue.');if(word!=='CLEAR DEMO STOCK')return toast('Reset cancelled.','');state.lastBackup={at:new Date().toISOString(),items:JSON.parse(JSON.stringify(state.items)),definitions:JSON.parse(JSON.stringify(state.definitions)),releases:JSON.parse(JSON.stringify(state.releases)),nextTag:state.nextTag};const n=state.items.length;state.items=[];state.definitions=[];state.releases=[];/* retain the next-tag counter; tag numbers are never intentionally reused */log('Demo stock reset','Stock Reset','ALL STOCK',`Cleared ${n} item records. Users and transaction history retained.`,'',String(n));save();toast('Demo stock cleared.','success');renderPage();}
  function restoreBackup(){if(!state.lastBackup)return; if(!confirm('Restore the last local stock backup? Current records will be backed up first.'))return;const cur={at:new Date().toISOString(),items:JSON.parse(JSON.stringify(state.items)),definitions:JSON.parse(JSON.stringify(state.definitions)),releases:JSON.parse(JSON.stringify(state.releases)),nextTag:state.nextTag};state.items=JSON.parse(JSON.stringify(state.lastBackup.items));state.definitions=JSON.parse(JSON.stringify(state.lastBackup.definitions));state.releases=JSON.parse(JSON.stringify(state.lastBackup.releases));state.nextTag=state.lastBackup.nextTag;state.lastBackup=cur;log('Stock backup restored','Stock Reset','LAST BACKUP','Restored local snapshot.');save();toast('Local backup restored.','success');renderPage();}
  function stockReportRows(){return state.items.map(i=>({'Part No':i.partNo,'Description':i.description,'Inventory Module':i.kind==='tool'?'Tools':'Parts','Serial No':i.serialNo,'Tag No':i.tagNo,'Lot/Batch':i.lotBatch,'Stock / Company-Store':i.stock||'','Physical Location':i.location||'','Qty On Hand':i.qtyOnHand,'Measure':i.measure,'Condition':i.condition,'Status':i.status,'Serviceability':effectiveServiceability(i),'Stock Status':stockStatus(i),'Expiry Date':i.expiryDate,'Calibration Date':i.calibrationDate,'Material Type':i.materialType,'Material Class':i.materialClass,'Tool PN':i.toolPn||'','Tool Code':i.toolCode,'Remarks':i.remarks,'Lot Controlled':!!(i.lotControlled||defFor(i.partNo)?.lotControlled),'Source Company':i.legacyCompany||'','Source Store':i.legacyStore||'','Source PART_NUM':i.legacySourcePartNo||'','Source PART_NAME':i.legacySourcePartName||'','Source QTY_IN_STR':i.legacySourceQty??'','Source PART_TYPE':i.legacyPartType||'','Source SER_NUM':i.legacySourceSerial||'','Source Condition':i.legacyConditionCode||'','Source FROM':i.legacyFrom||'','Source ORIGIN':i.legacyOrigin||'','Source DOC_NUM':i.legacyDocumentNo||'','Source INT_NUM':i.legacyInternalNo||'','Source AWB':i.legacyAWB||'','Source INTERNAL':i.legacyInternal||'','Source PU':i.legacyPU||'','Source STK_VALUE':i.legacyStockValue||'','Source LAST_PRICE':i.legacyLastPrice||'','Source DATE_MOV':i.legacySourceDate||'','Source POSITION_1':i.legacyPosition1||'','Source POSITION_2':i.legacyPosition2||'','Source Excel Row':i.legacySourceRow||''}));}
  function releaseReportRows(periodFilter=false){let list=[...state.releases];if(periodFilter){let start=$('#releaseStart')?.value||'',end=$('#releaseEnd')?.value||'';if(start)list=list.filter(r=>r.issuedAt.slice(0,10)>=start);if(end)list=list.filter(r=>r.issuedAt.slice(0,10)<=end);}return list.map(r=>{const i=state.items.find(x=>x.id===r.itemId)||{};return {'Release No':r.releaseNo||'','Issued At':r.issuedAt,'Part No':r.partNo,'Serial No':i.serialNo||'','Tag No':i.tagNo||'','Lot/Batch':i.lotBatch||'','Stock':i.stock||'AHY','Location':i.location||'','Tool PN':i.toolPn||'','Tool Code':i.toolCode||'','Aircraft Registration':r.aircraft,'Technician':r.technician,'WO/NRC':r.workRef||'','Qty Issued':r.qty,'Qty Returned':r.returnedQty,'Qty Outstanding':num(r.qty)-num(r.returnedQty),'Issued By':r.issuedBy,'Notes':r.note||''};});}
