  function exportRows(rows,filename,type='xlsx'){if(!rows.length)return toast('No rows to export.','error');if(typeof XLSX!=='undefined'&&type==='xlsx'){const ws=XLSX.utils.json_to_sheet(rows);const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Report');XLSX.writeFile(wb,filename.endsWith('.xlsx')?filename:filename+'.xlsx');}else{const keys=[...new Set(rows.flatMap(r=>Object.keys(r)))];const csv=[keys,...rows.map(r=>keys.map(k=>r[k]??''))].map(row=>row.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(',')).join('\r\n');const blob=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename.replace(/\.(xlsx|csv)$/i,'')+'.csv';a.click();URL.revokeObjectURL(a.href);}toast('Export created.','success');}
  function showStockPreview(){const rows=stockReportRows();$('#reportPreview').innerHTML=`<div class="statline"><span class="stat-chip"><strong>${rows.length}</strong> records</span><span class="stat-chip"><strong>${state.items.reduce((s,i)=>s+num(i.qtyOnHand),0)}</strong> on-hand units</span></div><div class="table-wrap"><table><thead><tr><th>Part No</th><th>Serial</th><th>Tag</th><th>Stock</th><th>Location</th><th>Qty</th><th>Condition</th><th>Status</th></tr></thead><tbody>${state.items.slice(0,20).map(i=>`<tr><td>${esc(i.partNo)}</td><td>${esc(i.serialNo||'—')}</td><td>${esc(i.tagNo)}</td><td>${esc(i.stock||'AHY')}</td><td>${esc(i.location||'—')}</td><td>${esc(i.qtyOnHand)}</td><td>${esc(i.condition)}</td><td>${esc(i.status)}</td></tr>`).join('')}</tbody></table></div><p class="reduced">Showing first 20 rows. Export includes every row.</p>`;}
