    if(a==='clear-issue-search'){const kind=actionEl.dataset.deliveryKind||deliveryKind();window.releaseStockQueriesByKind[kind]='';window.releaseStockPagesByKind[kind]=1;setDeliveryTab('issue',kind);return;}
    if(a==='clear-inventory-search'){const kind=actionEl.dataset.kind||((currentPage==='tools')?'tool':'part');window.inventorySearchFieldsByKind[kind]=blankInventorySearch();window[kind==='tool'?'toolPage':'partPage']=1;renderPage();return;}
    if(a==='clear-release-search'){const kind=actionEl.dataset.kind||deliveryKind();window.releaseReturnSearchFieldsByKind[kind]={releaseNo:'',partNo:'',serialNo:'',description:'',aircraft:'',technician:''};setDeliveryTab(window.deliveryTabs[kind]||'outstanding',kind);return;}
    if(a.startsWith('select-incoming-def:')){const d=state.definitions.find(x=>x.id===a.slice(20));if(d){const input=$('#incomingPart');if(input)input.value=d.partNo;const kindSelect=$('#incomingKind');if(kindSelect)kindSelect.value=d.materialType==='Tool'&&!d.supportsPart?'tool':'part';refreshIncomingStoreOptions();const list=$('#incomingPartSuggestions');if(list){list.innerHTML='';list.classList.add('hidden');}refreshSerialFields();const hint=$('#expiryHint');if(hint)hint.textContent=(d.materialType==='Chemical'||d.materialClass==='Chemical')?(d.indefiniteShelfLife?'Configured as indefinite shelf life; expiry date may be omitted.':'Chemical definitions require an expiry date unless indefinite shelf life is enabled.'):'Enable expiry tracking when applicable.';}return;}
