    if(a==='export-releases'){exportRows(releaseReportRows(),'azal-release-report.xlsx','xlsx');return;} if(a==='export-releases:part'||a==='export-releases:tool'){const k=a.split(':')[1];const subset=state.releases.filter(r=>getReleaseKind(r)===k);const old=state.releases;state.releases=subset;exportRows(releaseReportRows(),'azal-'+(k==='tool'?'tool-delivery':'parts-release')+'-report.xlsx','xlsx');state.releases=old;return;}
